let shdr;

async function setup() {
	S = max(windowWidth, windowHeight)
	let cnv = createCanvas(S, S, WEBGL);
	cnv.position((windowWidth - width) / 2, (windowHeight - height) / 2);
	//createCanvas(windowWidth, windowHeight, WEBGL)
	pixelDensity(1);
	noCursor();

	shdr = await createShader(resolveLygia(vert), resolveLygia(frag));
}

function draw() {
	shader(shdr);

	shdr.setUniform('u_resolution', [width, height]);
	shdr.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	shdr.setUniform("iFrame", frameCount);
	shdr.setUniform("u_time", millis() / 1000.0);

	rect(0, 0, width, height);
}

