float tieDye( vec2 st, float speed, float zoom, int N) {
    st -= 0.5;
    vec3 r = u_resolution.xxx;
    vec3 uv = vec3((2.0 * st.xyy- r)/r.x * zoom);
    uv.z = sineIn(u_time*speed);
